def run(_context):
    import json, adsk.cam, adsk.fusion

    cam = mb.get_cam()
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
            break

    if setup:
        # Get stock properties
        stock = setup.stock
        print("Stock mode:", stock.stockMode)
        print("Stock isParametric:", stock.isParametric)

        # Try to get stock dimensions
        if stock.isParametric:
            params = stock.parameters
            for p in params:
                print(f"  Stock param: {p.name} = {p.expression}")

        # Get setup parameters
        setup_params = setup.parameters
        for p in setup_params:
            if 'stock' in p.name.lower() or 'wcs' in p.name.lower() or 'origin' in p.name.lower() or 'offset' in p.name.lower():
                print(f"  Setup param: {p.name} = {p.expression}")

        # Check all setup params
        print("\nAll setup params:")
        for p in setup_params:
            try:
                print(f"  {p.name} = {p.expression}")
            except:
                print(f"  {p.name} = (no expression)")

