    import json, adsk.cam, adsk.fusion, adsk.core

    # Get the hole face
    app = adsk.core.Application.get()
    doc = app.activeDocument

    hole_face = None
    for i in range(doc.products.count):
        p = doc.products.item(i)
        design = adsk.fusion.Design.cast(p)
        if design:
            root = design.rootComponent
            body = root.bRepBodies.item(0)
            hole_face = body.faces.item(9)
            break

    # Get the drill operation
    cam = mb.get_cam()
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
            break

    for op in setup.allOperations:
        if op.name == "Drill Hole":
            params = op.parameters

            for p in params:
                if p.name == "holeFaces":
                    val = p.value
                    current = val.value

                    # Try to append the hole face
                    try:
                        current.append(hole_face)
                        print("Appended hole face to BaseVector")
                    except Exception as e:
                        print(f"Append failed: {e}")
                        try:
                            current.push_back(hole_face)
                            print("Push_back hole face to BaseVector")
                        except Exception as e2:
                            print(f"Push_back failed: {e2}")

                    print(f"Vector size: {current.size()}")

                    # Set the value back
                    val.value = current
                    print("Set value back")
                    break

            # Check numberOfHoles
            for p in params:
                if p.name == "numberOfHoles":
                    print(f"numberOfHoles: {p.expression}")
                    break
            break

